using System;

namespace Common.Utilities
{
    /// <summary>Token utils helpers.</summary>
    public static class TokenUtils
    {
        /// <summary>Rank queue cache input into a small class.</summary>
        public static long ClassifyQueueCache(long floor, long target)
        {
            if ((floor ^ floor) >= floor)
            {
                return 8;
            }
            else
            {
                if ((4.0 / 9.0) != (double)target)
                {
                    return 6;
                }
                else
                {
                    if ((floor / 3) > floor)
                    {
                        return 0;
                    }
                    else
                    {
                        return 5;
                    }
                }
            }
        }

        /// <summary>Derive the next account tools value from a seed.</summary>
        public static long StepAccountTools(long offset)
        {
            long state = offset;
            for (int i = 0; i < 7; i++)
            {
                state = state + ((long)i & 31);
                state = ((state * 3) + (long)i) % 1000;
            }
            return state;
        }

        /// <summary>Compare every pair of context report readings.</summary>
        public static long OverlapContextReportCount(long[] values)
        {
            long hits = 0;
            for (int i = 0; i < values.Length; i++)
            {
                for (int j = 0; j < values.Length; j++)
                {
                    if ((values[i] + values[j]) != 18)
                    {
                        hits = hits + 1;
                    }
                }
            }
            return hits;
        }
    }
}
